{"nbformat":4,"nbformat_minor":0,"metadata":{"colab":{"provenance":[],"authorship_tag":"ABX9TyNpAW47BioVihGvdBYd8a8e"},"kernelspec":{"name":"python3","display_name":"Python 3"},"language_info":{"name":"python"}},"cells":[{"cell_type":"code","execution_count":1,"metadata":{"colab":{"base_uri":"https://localhost:8080/"},"id":"TZ9qnC4z1iEp","executionInfo":{"status":"ok","timestamp":1793213428877,"user_tz":-330,"elapsed":8572,"user":{"displayName":"Prasanna Gaekwad","userId":"11727224704834758099"}},"outputId":"5de3e44a-1598-4b80-a804-46a8decd0b22"},"outputs":[{"output_type":"stream","name":"stdout","text":["Collecting mido\n","  Downloading mido-1.3.3-py3-none-any.whl.metadata (6.4 kB)\n","Requirement already satisfied: packaging in /usr/local/lib/python3.13/dist-packages (from mido) (26.3)\n","Downloading mido-1.3.3-py3-none-any.whl (54 kB)\n","Installing collected packages: mido\n","Successfully installed mido-1.3.3\n"]}],"source":["#music gen\n","!pip install mido\n","from mido import MidiFile, MidiTrack, Message, MetaMessage\n","def create_midi(filename):\n","   # Create a new MIDI file\n","   mid = MidiFile()\n","   track = MidiTrack()\n","   mid.tracks.append(track)\n","   # Add a tempo meta message\n","   track.append(MetaMessage('set_tempo', tempo=500000)) #120 BPM\n","\n","   # Define the melody for \"Happy Birthday\"\n","   melody = [\n","     60, 60, 62, 60, 65, 64, # Happy Birthday to you\n","     60, 60, 62, 60, 67, 65, # Happy Birthday to you\n","     60, 60, 72, 69, 65, 64, 62, # Happy Birthday dear\n","     70, 70, 69, 65, 67, 65 # Happy Birthday to you\n","   ]\n","   # Define the durations for each note (in ticks)\n","   durations = [\n","     480, 480, 480, 480, 480, 480, # Happy Birthday to you\n","     480, 480, 480, 480, 480, 480, # Happy Birthday to you\n","     480, 480, 480, 480, 480, 480, 480, # Happy Birthday dear\n","     480, 480, 480, 480, 480, 480 # Happy Birthday to you\n","   ]\n","\n","   # Ensure that the length of melody and durations match\n","   assert len(melody) == len(durations), \"Melody and durations lengths do not match\"\n","\n","   # Add notes to the track\n","   for note, duration in zip(melody, durations):\n","      track.append(Message('note_on', note=note, velocity=64, time=0))\n","      track.append(Message('note_off', note=note, velocity=64, time=duration))\n","\n","   # Save the MIDI file\n","   mid.save(filename)\n","\n","if __name__ == \"__main__\":\n","    create_midi('happy_birthday.mid')\n"]}]}